export const matrixColumns: ProductId[] = ["notion", "obsidian", "yuga", "citizen", "mere", "medplum", "oncobase"];

export type Cell = { t: string; tone?: "yes" | "no" | "unknown" };
const y = (t: string): Cell => ({ t, tone: "yes" });
const n = (t: string): Cell => ({ t, tone: "no" });
const u = (t = "Not stated"): Cell => ({ t, tone: "unknown" });
const c = (t: string): Cell => ({ t });

