/** Table order: Oncobase first, as the reference column that stays in view, then the rest. */
export const matrixOrder: ProductId[] = ["oncobase", ...matrixColumns.filter((id) => id !== "oncobase")];
export const cellFor = (row: { cells: Cell[] }, id: ProductId): Cell => row.cells[matrixColumns.indexOf(id)]!;

const productById = (id: ProductId) => products.find((product) => product.id === id)!;
export const productName = (id: ProductId) => productById(id).name;

/** The text of `public/compare.md`, the markdown twin of /compare. */
export function renderCompareMd(): string {
  const goalsMd = goals
    .map(
      (goal) =>
        `- **${goal.label}:** start with ${productName(goal.pick)}${goal.also.length ? ` (also consider ${goal.also.map(productName).join(", ")})` : ""}. ${goal.why} ${goal.moveOn}`,
    )
    .join("\n");
  const cards = products
    .map(
      (product) =>
        `### ${product.name}\n\n${product.kind}. ${product.tagline} ${product.url}\n\n- **Great at:** ${product.great}\n- **Consider:** ${product.consider}`,
    )
    .join("\n\n");
  const head = ["Question", ...matrixOrder.map(productName)];
  const table = [
    `| ${head.join(" | ")} |`,
    `| ${head.map(() => "---").join(" | ")} |`,
    ...matrix.map((row) => `| ${row.label} | ${matrixOrder.map((id) => cellFor(row, id).t).join(" | ")} |`),
  ].join("\n");
  const pieceTable = (pieces: Piece[]) =>
    ["| Piece | License | What you get |", "| --- | --- | --- |", ...pieces.map((p) => `| [${p.name}](${p.url}) | ${p.license} | ${p.gives} |`)].join("\n");
  const also = alsoWorthKnowing.map((item) => `- [${item.name}](${item.url}): ${item.text}`).join("\n");
  const sources = compareSources.map((source) => `- [${source.name}](${source.url})`).join("\n");
  return `# How Oncobase compares

${compareHeroLede}

${compareDisclosure}

${notSure}

Page: ${SITE_URL}/compare. Source: ${REPO_URL}. Agent-readable feature list: ${SITE_URL}/features.md.

## Which should I use?

${goalsMd}

## Side by side

${table}

"Not stated" means the product's public site or repository doesn't say.

## Each option

${cards}

## If you're building your own

Oncobase is MIT licensed, so a family or a company can reuse it, and an agent can read /features.md to see everything it offers. If you handle other people's health information, check which rules apply to you: Oncobase carries no compliance certification.

### Reusable code in Oncobase

Only the CLI is on npm. The rest lives under \`packages/\` in the repository.

${pieceTable(oncobasePieces)}

### Other open-source projects worth building on

${pieceTable(otherOpenSource)}

## Also worth knowing

${also}

## Sources

${sources}

Checked ${COMPARE_ASOF}.
`;
}
